import React, { useState } from "react";

function Navbar({ activePage, setActivePage }) {
  const [isOpen, setIsOpen] = useState(false);

  const menuItems = [
    { id: "home", label: "Home", icon: "🏠" },
    { id: "about-ins", label: "About INS", icon: "🔬" },
    { id: "about-sources", label: "About INS Sources", icon: "📚" },
    { id: "about-risk", label: "About Risk Score", icon: "📊" },
    { id: "how-it-works", label: "How SAFE BITE Works", icon: "⚙️" },
  ];

  const handleNavClick = (pageId) => {
    setActivePage(pageId);
    setIsOpen(false);
  };

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <div className="navbar-brand" onClick={() => handleNavClick("home")}>
          <span className="brand-logo">🛡️</span>
          <span className="brand-name">SAFE BITE</span>
        </div>

        {/* Desktop Menu links */}
        <div className="navbar-menu-desktop">
          {menuItems.map((item) => (
            <button
              key={item.id}
              className={`nav-link ${activePage === item.id ? "active" : ""}`}
              onClick={() => handleNavClick(item.id)}
            >
              {item.label}
            </button>
          ))}
        </div>

        {/* Hamburger toggle button */}
        <button
          className={`hamburger-btn ${isOpen ? "open" : ""}`}
          onClick={() => setIsOpen(!isOpen)}
          aria-label="Toggle navigation menu"
        >
          <span className="hamburger-line"></span>
          <span className="hamburger-line"></span>
          <span className="hamburger-line"></span>
        </button>
      </div>

      {/* Slide-out Navigation Drawer */}
      <div className={`nav-drawer ${isOpen ? "open" : ""}`}>
        <div className="drawer-header">
          <div className="navbar-brand">
            <span className="brand-logo">🛡️</span>
            <span className="brand-name">SAFE BITE</span>
          </div>
          <button className="close-btn" onClick={() => setIsOpen(false)}>
            &times;
          </button>
        </div>

        <div className="drawer-content">
          {menuItems.map((item) => (
            <button
              key={item.id}
              className={`drawer-link ${activePage === item.id ? "active" : ""}`}
              onClick={() => handleNavClick(item.id)}
            >
              <span className="link-icon">{item.icon}</span>
              <span className="link-label">{item.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Backdrop overlay for closing the drawer */}
      {isOpen && (
        <div className="drawer-overlay" onClick={() => setIsOpen(false)}></div>
      )}
    </nav>
  );
}

export default Navbar;
